await scenario('R2 seven days only foreground successful network visits; own wins and reload does not renew',async()=>{const f=fixture(),w=await f.start();await f.own(w);await w.nav(1);await w.nav(2);let s=await f.state(w),other=s.items.find(x=>x.objectId===2);assert.equal(other.source,'substitution');assert.equal(Number(other.expiresAt),f.env.now+7*DAY);assert.equal(s.items.find(x=>x.objectId===1).source,'own');f.env.now+=6*DAY;await w.nav(2,'cors');assert.equal(Number((await f.state(w)).items.find(x=>x.objectId===2).expiresAt),Number(other.expiresAt),'JS fetch does not renew');f.env.network=false;assert.equal((await w.nav(2)).status,200);assert.equal(Number((await f.state(w)).items.find(x=>x.objectId===2).expiresAt),Number(other.expiresAt),'cached navigation does not renew');f.env.now+=DAY+1;await f.maintenance(w);s=await f.state(w);assert(!s.items.some(x=>x.objectId===2),'expired clean substitution removed');assert(s.items.some(x=>x.objectId===1),'own is not expired');assert.notEqual((await w.nav(2)).status,200,'expired direct URL unavailable');f.env.network=true;await w.nav(2);await f.own(w,[1,2]);s=await f.state(w);assert.equal(s.items.filter(x=>x.objectId===2).length,1);assert.equal(s.items.find(x=>x.objectId===2).source,'own');});
