await scenario('R1 recognized legacy bodies count toward budget and refuse new growth while live',async()=>{const f=fixture();const legacy=await seedLegacy(f,40*MiB,20*MiB);f.env.clients=[{id:'legacy-live',url:'https://field.test'+legacy.path,postMessage(){}}];const w=await f.start();await f.own(w,[1]);const before=await f.state(w);assert(!before.items.some(x=>x.objectId===2),'unknown non-own legacy document is not discoverable');assert(before.cacheBytes>=60*MiB,'INTENDED_RED legacy shell and document bodies must be counted');f.env.padding=45*MiB;const answer=await w.message('CACHE_CHECKLIST',{url:'https://field.test/pilot/construction-control/objects/1/checklist',scope:'legacy-capacity',attempt:'legacy-capacity'});assert.equal(answer?.ok,false,'legacy bytes leave insufficient growth budget');assert.equal(answer?.reasonCode,'CACHE_BUDGET_EXHAUSTED');assert(f.env.stores.has(legacy.documentName)&&f.env.stores.has(legacy.shellName));assert(!(await f.state(w)).items.some(x=>x.objectId===1));});
