await scenario('R5 failed corrupt or metadata-blocked legacy migration preserves exact source',async()=>{for(const failure of ['cacheFailure','corruptDocumentWrites','failRevisionWrite']){const f=fixture(),legacy=await seedLegacy(f);f.env.clients=[{id:'legacy-live',url:'https://field.test'+legacy.path,postMessage(){}}];f.env.operations=[{id:'legacy-pending',scope:'73:device:2',userId:73,objectId:2,status:'uncertain'}];const w=await f.start();await f.own(w,[2]);f.env.clients=[];f.env[failure]=true;try{await f.maintenance(w);}catch{}assert(f.env.failureHooks>0,'INTENDED_RED legacy migration must reach injected '+failure);assert(f.env.stores.has(legacy.documentName),'failed '+failure+' retains source cache');assert.equal(await(await(await f.caches.open(legacy.documentName)).match(legacy.path)).text(),legacy.html,'exact source retained for '+failure);assert(f.env.stores.has(legacy.shellName),'compatible source resources retained for '+failure);assert.equal(f.env.idbWrites,0);}});
await scenario('R6 foreign legacy bytes remain isolated until their actor returns',async()=>{const f=fixture(),legacy=await seedLegacy(f,0,0,95),w=await f.start();await f.own(w,[]);await f.maintenance(w);assert(f.env.stores.has(legacy.documentName),'INTENDED_RED current actor cannot erase foreign legacy cache');assert.equal(await(await(await f.caches.open(legacy.documentName)).match(legacy.path)).text(),legacy.html);assert(f.env.stores.has(legacy.shellName));const state=await f.state(w);assert(state.cacheBytes>=Buffer.byteLength(legacy.html)+9,'foreign bytes counted');assert(!state.items.some(x=>x.objectId===2));f.env.network=false;assert.notEqual((await w.nav(2)).status,200,'foreign document inaccessible to73');await(await f.caches.open('fmonitor2-field-meta')).put('/pilot/__field-identity__',new Response(JSON.stringify({userId:95,epoch:2,tombstone:false})));const own=await w.message('FIELD_SET_OWN_OBJECTS',{userId:95,epoch:2,setVersion:'returning95',items:[{userId:95,objectId:2,checklistUrl:legacy.path,address:'Returning actor object',registrationNumber:'95-2',completed:false}]});assert.equal(own?.ok,true);assert.equal((await w.message('FIELD_CACHE_MAINTAIN',{userId:95,epoch:2}))?.ok,true);const recovered=await w.nav(2);assert.equal(recovered.status,200);assert((await recovered.text()).includes('LEGACY EXACT DATA'));assert(!f.env.stores.has(legacy.documentName),'returning actor can safely migrate legacy source');assert.equal(f.env.idbWrites,0);});
