async function coldBootstrap(path='/pilot/construction-control/objects/2/checklist'){const f=fixture(),w=await f.start();await(await f.caches.open('fmonitor2-field-meta')).delete('/pilot/__field-identity__');const source={id:'first-page',type:'window',frameType:'top-level',url:'https://field.test'+path,postMessage(){}};f.env.clients=[source];return {...f,w,source};}
await scenario('R2 cold canonical bootstrap becomes bounded visit and survives worker restart',async()=>{for(const path of ['/pilot/objects/2/checklist','/pilot/construction-control/objects/2/checklist'])for(const frameType of ['top-level','auxiliary']){const f=await coldBootstrap(path);f.source.frameType=frameType;f.source.url='https://field.test'+(path.startsWith('/pilot/objects/')?'/pilot/construction-control/objects/2/checklist':'/pilot/objects/2/checklist');const reply=await f.w.message('FIELD_ESTABLISH_ACTOR',{url:'https://field.test'+path},f.source);assert.equal(reply?.ok,true);assert.equal(reply.cacheReady,true,'INTENDED_RED initial checklist bootstrap records managed availability');const item=(await f.state(f.w)).items.find(x=>x.objectId===2);assert.equal(item?.source,'substitution');assert.equal(Number(item.expiresAt),f.env.now+7*DAY);f.env.now+=DAY;await f.w.message('FIELD_ESTABLISH_ACTOR',{url:'https://field.test'+path},f.source);assert.equal((await f.state(f.w)).items.find(x=>x.objectId===2).expiresAt,item.expiresAt,'actor recheck does not renew');f.env.network=false;const restarted=f.worker(f.env.build);assert.equal((await restarted.nav(2)).status,200,'cold first checklist remains available after restart');f.env.now+=7*DAY;assert.notEqual((await restarted.nav(2)).status,200,'bootstrap visit expires normally');}});
