await scenario('R2 invalid bootstrap sources or metadata cannot admit documents',async()=>{for(const variant of ['dashboard','foreign','different-object','missing-client','nested','worker-client','unknown-frame','invalid-epoch','invalid-build','invalid-metadata']){const f=await coldBootstrap();let source=f.source;if(variant==='dashboard')source={...source,url:'https://field.test/pilot/dashboard'};if(variant==='foreign')source={...source,url:'https://foreign.test/pilot/objects/2/checklist'};if(variant==='different-object')source={...source,url:'https://field.test/pilot/objects/3/checklist'};if(variant==='nested')source={...source,frameType:'nested'};if(variant==='worker-client')source={...source,type:'worker'};if(variant==='unknown-frame')source={...source,frameType:'none'};f.env.clients=variant==='missing-client'?[]:[source];if(variant==='invalid-metadata')f.env.metadataOverride={userId:95};await f.w.message('FIELD_ESTABLISH_ACTOR',{url:f.source.url,...(variant==='invalid-epoch'?{epoch:1.5}:{}),...(variant==='invalid-build'?{generation:'b'.repeat(64)}:{})},source);const state=await f.w.message('FIELD_CACHE_STATUS');assert(!state?.items?.some(x=>x.objectId===2),'unqualified source has no catalogue availability');for(const[name,cache]of f.env.stores)if(name.includes('field-doc-'))assert.equal((await cache.keys()).length,0,'INTENDED_RED unqualified bootstrap cannot cache: '+variant);f.env.network=false;assert.notEqual((await f.w.nav(2)).status,200);}});
await scenario('R6 late bootstrap cannot undo logout or actor replacement',async()=>{for(const transition of ['logout','switch','generation']){const f=await coldBootstrap();f.env.holdNext=true;const pending=f.w.message('FIELD_ESTABLISH_ACTOR',{url:f.source.url},f.source);while(!f.env.releaseResponse)await new Promise(r=>setTimeout(r,0));if(transition==='logout')await f.w.message('FIELD_LOGOUT');else if(transition==='generation')await(await f.caches.open('fmonitor2-field-meta')).put('/pilot/__field-generation__',new Response('b'.repeat(64)));else await(await f.caches.open('fmonitor2-field-meta')).put('/pilot/__field-identity__',new Response(JSON.stringify({userId:95,epoch:2,tombstone:false})));f.env.releaseResponse(new Response('<main data-checklist data-user-id="73" data-object-id="2">late</main>',{headers:{'content-type':'text/html'}}));await pending;const current=(await f.w.message('FIELD_CHECK_ACTOR')).identity;if(transition==='logout')assert.equal(current?.tombstone,true,'INTENDED_RED late bootstrap cannot resurrect logout');else if(transition==='switch')assert.equal(current?.userId,95,'late bootstrap cannot replace newer actor');else assert.notEqual(current?.userId,73,'old generation cannot publish bootstrap actor');}});

async function reached(env,key){for(let i=0;i<300&&!env[key];i++)await new Promise(r=>setTimeout(r,5));assert.equal(typeof env[key],'function','injected barrier reached: '+key);}
await scenario('R4 late replacement rollback preserves exact predecessor and pending data',async()=>{for(const transition of ['logout','switch','generation','cancel']){const f=fixture(),w=await f.start();await f.own(w);await w.nav(1);const name='fmonitor2-field-doc-'+f.env.build+'-73',path='/pilot/construction-control/objects/1/checklist',cache=await f.caches.open(name),before=await(await cache.match(path)).text();f.env.operations=[{id:'rollback',scope:'73:device:1',status:'uncertain',clientOperationId:'rollback-uuid',wire:'immutable'}];f.env.blobs=[{id:'rollback',blob:new Blob(['ROLLBACK PHOTO'])}];const operation=JSON.stringify(f.env.operations);f.env.revision=1;f.env.holdDocumentPut=true;const pending=transition==='cancel'?w.message('CACHE_CHECKLIST',{url:'https://field.test'+path,scope:'rollback',attempt:'rollback'}):w.nav(1);await reached(f.env,'releaseDocumentPut');const meta=await f.caches.open('fmonitor2-field-meta');if(transition==='logout')await w.message('FIELD_LOGOUT');else if(transition==='switch')await meta.put('/pilot/__field-identity__',new Response(JSON.stringify({userId:95,epoch:2,tombstone:false})));else if(transition==='generation')await meta.put('/pilot/__field-generation__',new Response('b'.repeat(64)));else await w.message('CANCEL_CHECKLIST_WARMUPS',{scope:'rollback',attempt:'rollback'});f.env.releaseDocumentPut();await pending;if(transition==='cancel'){for(let i=0;i<300;i++){const settled=await cache.match(path);if(settled&&await settled.text()===before)break;await new Promise(r=>setTimeout(r,5));}}const retained=await cache.match(path);assert(retained,'INTENDED_RED late '+transition+' must not delete predecessor');assert.equal(await retained.text(),before,'exact predecessor restored for '+transition);assert.equal(JSON.stringify(f.env.operations),operation);assert.equal(await f.env.blobs[0].blob.text(),'ROLLBACK PHOTO');assert.equal(f.env.idbWrites,0);await meta.put('/pilot/__field-identity__',new Response(JSON.stringify({userId:73,epoch:1,tombstone:false})));await meta.put('/pilot/__field-generation__',new Response(f.env.build));assert.equal((await f.state(w)).pendingWriteCount,0,'displaced actor rollback token released: '+transition);}});
await scenario('R5 repeated HTML promotion emits each current engine once',async()=>{for(const multiline of [false,true]){const f=fixture();let w=await f.start();await f.own(w);await w.nav(1);const path='/pilot/construction-control/objects/1/checklist',cache=await f.caches.open('fmonitor2-field-doc-'+f.env.build+'-73'),response=await cache.match(path),body=await response.text(),engines=['field-offline-store.js','field-offline-lifecycle.js','field-offline-sync.js','field-offline-photo.js','field-offline.js','checklist.js'];const tags=engines.map((name,i)=>`<script defer data-fixture="${i}" src=${(multiline&&i%2)?"'":'"'}/pilot/assets/${name}?v=${f.env.build}${(multiline&&i%2)?"'":'"'}>${multiline?'\n  ':''}</script>`).join('');await cache.put(path,new Response('<html><head>'+tags.slice(0,tags.indexOf('<script defer data-fixture="2"'))+'</head><body>'+body+tags.slice(tags.indexOf('<script defer data-fixture="2"'))+'<script src="/unrelated.js" defer></script></body></html>',{headers:response.headers}));for(const next of ['b','c']){f.env.build=next.repeat(64);w=f.worker(f.env.build);await w.lifecycle('install');await w.lifecycle('activate');await f.maintenance(w);f.env.network=false;const html=await(await w.nav(1)).text();f.env.network=true;for(const name of engines){const matches=[...html.matchAll(/<script\b[^>]*\bsrc\s*=\s*(["'])(.*?)\1[^>]*>/gi)].map(m=>m[2]).filter(url=>new URL(url,'https://field.test').pathname==='/pilot/assets/'+name);assert.deepEqual(matches,['/pilot/assets/'+name+'?v='+f.env.build],'INTENDED_RED exactly one current '+name);}assert.equal((html.match(/src="\/unrelated.js"/g)||[]).length,1,'unrelated script retained');assert(!html.includes('undefined'));}}});


await scenario('R7 lifecycle awaits activating worker before runtime and actor handshake',async()=>{for(const finalState of ['activated','redundant']){const calls=[],listeners=new Set();let opens=0;const active={state:'activating',addEventListener(type,listener){listeners.add(listener);},removeEventListener(type,listener){listeners.delete(listener);},postMessage(message,ports){calls.push({type:message.type,state:this.state});ports[0].postMessage(message.type==='FIELD_RUNTIME_INFO'?{protocol:3,generation:'a'.repeat(64)}:message.type==='FIELD_CHECK_ACTOR'?{ok:true,identity:{userId:73,epoch:0,tombstone:false}}:{ok:true});}};const registration={active,installing:null,waiting:null};class Channel{constructor(){this.port1={};this.port2={postMessage:value=>queueMicrotask(()=>this.port1.onmessage?.({data:value}))};}}const sandbox={document:{body:{dataset:{authenticatedUserId:'73'},prepend(){}},querySelector:()=>null,createElement:()=>({dataset:{},setAttribute(){},replaceChildren(){},append(){}}),createTextNode:x=>x},navigator:{serviceWorker:{controller:null,getRegistration:async()=>registration,register:async()=>registration,addEventListener(){}}},isSecureContext:true,location:{href:'https://field.test/pilot/objects'},FMonitorFieldStore:{open:async()=>{opens++;},deviceId:async()=>'device',actorState:async()=>({activeUserId:73,epoch:0,tombstonedAt:null}),onActorChange(){}},MessageChannel:Channel,setTimeout,clearTimeout,console,URL};vm.runInNewContext(fs.readFileSync(new URL('field-offline-lifecycle.js',ROOT),'utf8'),sandbox);const ready=sandbox.FMonitorFieldLifecycle.ready;ready.catch(()=>{});await new Promise(r=>setTimeout(r,20));const early=calls.slice();active.state=finalState;for(const listener of [...listeners])listener();if(finalState==='activated')await ready;else await assert.rejects(ready);assert.deepEqual(early,[],'INTENDED_RED activating worker is not ready for handshake');assert.equal(opens,finalState==='activated'?1:0);assert(calls.every(x=>x.state==='activated'),'no pre-activation runtime or identity calls');}});


const cachedBody=async(cache,path)=>{const response=await cache.match(path);return response?await response.text():null;};
const metaItem=async(f,key,id=2)=>{const response=await(await f.caches.open('fmonitor2-field-meta')).match('/pilot/'+key);return response?(await response.json()).users?.['73']?.[String(id)]??null:null;};
await scenario('R4 all admission owners roll back catalogue denial and revision failures',async()=>{for(const owner of ['foreground','bootstrap','warmup'])for(const failure of ['failCatalogueWrite','failDeniedWrite','failRevisionWrite'])for(const predecessor of [false,true]){const f=fixture(),w=await f.start();await f.own(w,owner==='warmup'?[2]:[]);if(predecessor)await w.nav(2);const path='/pilot/construction-control/objects/2/checklist',cache=await f.caches.open('fmonitor2-field-doc-'+f.env.build+'-73'),before=await cachedBody(cache,path),catalogue=await metaItem(f,'__field-cache-catalogue__');f.env.operations=[{id:'failure-photo',scope:'73:device:2',status:'uncertain',clientOperationId:'failure-uuid',wire:'failure-wire'}];f.env.blobs=[{id:'failure-photo',blob:new Blob(['FAILURE PHOTO'])}];const queue=JSON.stringify(f.env.operations);let source;if(owner==='bootstrap'){await(await f.caches.open('fmonitor2-field-meta')).delete('/pilot/__field-identity__');source={id:'bootstrap-failure',type:'window',frameType:'top-level',url:'https://field.test'+path,postMessage(){}};f.env.clients=[source];}f.env.now+=DAY;f.env.revision=1;f.env[failure]=true;const answer=owner==='foreground'?await w.nav(2):owner==='bootstrap'?await w.message('FIELD_ESTABLISH_ACTOR',{url:source.url},source):await w.message('CACHE_CHECKLIST',{url:'https://field.test'+path,scope:'failure',attempt:'failure'});assert(f.env.failureHooks>0,'failure hook reached '+owner+'/'+failure);assert.equal(await cachedBody(cache,path),before,'INTENDED_RED exact predecessor/no new bytes '+owner+'/'+failure+'/'+predecessor);assert.deepEqual(await metaItem(f,'__field-cache-catalogue__'),catalogue,'failed record cannot publish/renew metadata');if(owner==='foreground')assert.match(await answer.text(),/revision-1/,'successful online response preserved despite cache failure');else assert.notEqual(answer?.cacheReady??answer?.ok,true,'failed cache write is not ready');const state=await f.state(w);assert.equal(state.pendingWriteCount,0,'all admitted tokens resolved');assert.equal(state.items.some(x=>x.objectId===2),predecessor,'only previous valid object discoverable');const restarted=f.worker(f.env.build);f.env.network=false;const offline=await restarted.nav(2);if(predecessor)assert.equal(await offline.text(),before);else assert.notEqual(offline.status,200);assert.equal(JSON.stringify(f.env.operations),queue);assert.equal(await f.env.blobs[0].blob.text(),'FAILURE PHOTO');assert.equal(f.env.idbWrites,0);}});
await scenario('R4 optional maintenance failure cannot strand a committed foreground write',async()=>{const f=fixture(),w=await f.start();await f.own(w,[]);await w.nav(2);f.env.now+=DAY;f.env.revision=1;f.env.catalogueWriteCountdown=2;assert.match(await(await w.nav(2)).text(),/revision-1/);assert(f.env.failureHooks>0,'maintenance fault reached after record');const state=await f.state(w);assert.equal(state.pendingWriteCount,0,'INTENDED_RED committed write releases predecessor before maintenance');assert.equal(state.items.find(x=>x.objectId===2).expiresAt,f.env.now+7*DAY);f.env.network=false;assert.match(await(await w.nav(2)).text(),/revision-1/);});
