await scenario('R6 primary denial persistence failure remains closed across restart',async()=>{const f=fixture(),w=await f.start();await f.own(w,[]);await w.nav(2);const path='/pilot/construction-control/objects/2/checklist',cache=await f.caches.open('fmonitor2-field-doc-'+f.env.build+'-73'),body=await cachedBody(cache,path);f.env.operations=[{id:'denial-pending',scope:'73:device:2',status:'uncertain',wire:'DENIAL WIRE'}];f.env.blobs=[{id:'denial-pending',blob:new Blob(['DENIAL PHOTO'])}];f.env.failDeniedWrite=true;f.env.status=403;assert.equal((await w.nav(2)).status,403);assert(f.env.failureHooks>0);f.env.network=false;let restarted=f.worker(f.env.build);assert.notEqual((await restarted.nav(2)).status,200,'INTENDED_RED denied object stays closed after restart');assert(!(await f.state(restarted)).items.some(x=>x.objectId===2));assert.equal(await cachedBody(cache,path),body);f.env.network=true;f.env.status=200;f.env.failCatalogueWrite=true;await restarted.nav(2);f.env.network=false;restarted=f.worker(f.env.build);assert.notEqual((await restarted.nav(2)).status,200,'failed restoration cannot clear durable denial');f.env.network=true;await restarted.nav(2);f.env.network=false;assert.equal((await restarted.nav(2)).status,200,'complete fresh record clears denial');assert.equal(f.env.operations[0].wire,'DENIAL WIRE');assert.equal(await f.env.blobs[0].blob.text(),'DENIAL PHOTO');assert.equal(f.env.idbWrites,0);});
await scenario('R6 own-set second-write failure preserves previously confirmed ownership',async()=>{for(const initial of [[],[2]]){const f=fixture(),w=await f.start();await f.own(w,initial);await w.nav(2);const meta=await f.caches.open('fmonitor2-field-meta'),priorOwn=await(await meta.match('/pilot/__field-cache-own-set__')).text(),priorCatalogue=await metaItem(f,'__field-cache-catalogue__'),prior=await f.state(w);f.env.failCatalogueWrite=true;let reply;try{reply=await w.message('FIELD_SET_OWN_OBJECTS',{setVersion:'failed-change',items:initial.length?[]:[{userId:73,objectId:2,checklistUrl:'/pilot/construction-control/objects/2/checklist',address:'Replacement',completed:false}]});}catch{}assert.notEqual(reply?.ok,true);assert.equal(await(await meta.match('/pilot/__field-cache-own-set__')).text(),priorOwn,'INTENDED_RED own-set rollback preserves prior root');assert.deepEqual(await metaItem(f,'__field-cache-catalogue__'),priorCatalogue);assert.deepEqual((await f.state(w)).items,prior.items);}});
