await scenario('R4 public offline legacy promotion resolves admission on success and revision failure',async()=>{for(const revisionFailure of [false,true]){const f=fixture(),w=await f.start();await f.own(w,[2]);const legacy=await seedLegacy(f),target=await f.caches.open('fmonitor2-field-doc-'+f.env.build+'-73');f.env.failRevisionWrite=revisionFailure;f.env.network=false;const response=await w.nav(2);assert.equal(response.status,200);const html=await response.text();assert(html.includes('LEGACY EXACT DATA')&&html.includes('field-offline-store.js?v='+f.env.build),'compatible legacy body returned');if(revisionFailure){assert(f.env.failureHooks>0,'post-put revision fault reached through promotion');assert.equal(await cachedBody(target,legacy.path),null,'failed new promotion leaves no incomplete target');}else assert.equal(await cachedBody(target,legacy.path),html,'successful promotion saved');assert.equal(await cachedBody(await f.caches.open(legacy.documentName),legacy.path),legacy.html,'exact legacy source retained');assert.equal((await f.state(w)).pendingWriteCount,0,'INTENDED_RED promotion token released');const restarted=f.worker(f.env.build);assert.equal((await restarted.nav(2)).status,200,'affirmative-access source usable after restart');assert.equal(f.env.idbWrites,0);}});
await scenario('R6 exact cache checks return useful hashes without mutation',async()=>{for(const legacyContent of [false,true]){const f=fixture(),w=await f.start();await f.own(w,[2]);let path='/pilot/construction-control/objects/2/checklist';if(legacyContent)path=(await seedLegacy(f)).path;else await w.nav(2);const snapshot=async()=>{const all=[];for(const [name,cache]of f.env.stores)for(const request of await cache.keys())all.push([name,request.url,await(await cache.match(request)).text()]);return JSON.stringify(all);};const before=await snapshot(),source=legacyContent?await(await f.caches.open('fmonitor2-checklist-doc-v8-73')).match(path):await(await f.caches.open('fmonitor2-field-doc-'+f.env.build+'-73')).match(path),hash=Buffer.from(await crypto.subtle.digest('SHA-256',await source.arrayBuffer())).toString('hex');const reply=await w.message('CHECK_CHECKLIST_CACHE',{url:'https://field.test'+path,contentHash:hash});assert.equal(reply?.ok,true,'confirmed current/legacy cache check succeeds');assert.equal(reply.contentHash,hash);assert.equal(await snapshot(),before,'INTENDED_RED read-only cache check cannot promote or mutate metadata');const mismatch=await w.message('CHECK_CHECKLIST_CACHE',{url:'https://field.test'+path,contentHash:'wrong'});assert.equal(mismatch?.ok,false);assert.equal(await snapshot(),before);assert.equal((await f.state(w)).pendingWriteCount,0);}});

await scenario('R6 incomplete ownership rollback survives restart with previous confirmed view',async()=>{for(const initial of [[],[2]]){const f=fixture(),w=await f.start();await f.own(w,initial);await w.nav(2);const prior=await f.state(w),path='/pilot/construction-control/objects/2/checklist',cache=await f.caches.open('fmonitor2-field-doc-'+f.env.build+'-73'),body=await cachedBody(cache,path);f.env.failOwnRestoreAfterCatalogue=true;f.env.failCatalogueWrite=true;const next=initial.length?[]:[{userId:73,objectId:2,checklistUrl:path,address:'New own',completed:false}];assert.equal((await w.message('FIELD_SET_OWN_OBJECTS',{setVersion:'double-failed',items:next}))?.ok,false);assert(f.env.ownRestoreFailures>0,'second ownership failure reached');const restarted=f.worker(f.env.build),state=await f.state(restarted);assert.deepEqual(state.items,prior.items,'INTENDED_RED restart retains previous confirmed ownership/discovery');assert.equal(state.limited,true);assert.equal(state.reasonCode,'CACHE_STATE_INDETERMINATE');f.env.now+=8*DAY;await restarted.message('FIELD_CACHE_MAINTAIN');assert.equal(await cachedBody(cache,path),body,'indeterminate ownership cannot delete bytes');const recovered=await restarted.message('FIELD_SET_OWN_OBJECTS',{setVersion:'recovered',items:next});assert.equal(recovered?.ok,true);const recoveredState=await f.state(f.worker(f.env.build));assert.notEqual(recoveredState.reasonCode,'CACHE_STATE_INDETERMINATE','complete fresh own-set clears durable limitation');if(next.length)assert.equal(recoveredState.items.find(x=>x.objectId===2)?.source,'own');assert.equal(f.env.idbWrites,0);}});
await scenario('R6 foreign maintenance preserves indeterminate ownership and legacy source bytes',async()=>{const f=fixture();let w=await f.start();await f.own(w,[2]);await w.nav(2);const oldBuild=f.env.build,oldName='fmonitor2-field-doc-'+oldBuild+'-73',path='/pilot/construction-control/objects/2/checklist',old=await cachedBody(await f.caches.open(oldName),path),legacy=await seedLegacy(f);f.env.operations=[{id:'foreign-indeterminate',scope:'73:device:2',status:'uncertain',wire:'FOREIGN WIRE'}];f.env.blobs=[{id:'foreign-indeterminate',blob:new Blob(['FOREIGN PHOTO'])}];f.env.failOwnRestoreAfterCatalogue=true;f.env.failCatalogueWrite=true;assert.equal((await w.message('FIELD_SET_OWN_OBJECTS',{setVersion:'failed-removal',items:[]}))?.ok,false);for(const next of ['b','c']){f.env.build=next.repeat(64);w=f.worker(f.env.build);await w.lifecycle('install');await w.lifecycle('activate');}await(await f.caches.open('fmonitor2-field-meta')).put('/pilot/__field-identity__',new Response(JSON.stringify({userId:95,epoch:2,tombstone:false})));assert.equal((await w.message('FIELD_SET_OWN_OBJECTS',{userId:95,epoch:2,setVersion:'other-actor',items:[]}))?.ok,true);await w.message('FIELD_CACHE_MAINTAIN',{userId:95,epoch:2});assert(f.env.stores.has(oldName),'INTENDED_RED foreign indeterminate generation must not be pruned');assert.equal(await cachedBody(await f.caches.open(oldName),path),old);assert.equal(await cachedBody(await f.caches.open(legacy.documentName),path),legacy.html);assert(f.env.stores.has(legacy.shellName));await(await f.caches.open('fmonitor2-field-meta')).put('/pilot/__field-identity__',new Response(JSON.stringify({userId:73,epoch:3,tombstone:false})));const returned=await w.message('FIELD_CACHE_STATUS',{userId:73,epoch:3});assert.equal(returned?.limited,true);assert.equal(returned.items.find(x=>x.objectId===2)?.source,'own');assert.equal(f.env.operations[0].wire,'FOREIGN WIRE');assert.equal(await f.env.blobs[0].blob.text(),'FOREIGN PHOTO');assert.equal(f.env.idbWrites,0);});
await scenario('R1 removed-own bytes stay indexed until safe reclamation makes room for new own objects',async()=>{for(const protection of ['clean','pending','unknown']){const f=fixture(),w=await f.start();await f.own(w,[1]);f.env.fullEngineHtml=true;f.env.padding=60*MiB;await w.nav(1);const path='/pilot/construction-control/objects/1/checklist',cache=await f.caches.open('fmonitor2-field-doc-'+f.env.build+'-73');assert(await cache.match(path));const originalHash=protection==='pending'?Buffer.from(await crypto.subtle.digest('SHA-256',await(await cache.match(path)).arrayBuffer())).toString('hex'):null;if(protection==='pending'){f.env.operations=[{id:'retired-own',scope:'73:device:1',status:'uncertain',wire:'RETIRED WIRE'}];f.env.blobs=[{id:'retired-own',blob:new Blob(['RETIRED PHOTO'])}];}if(protection==='unknown')f.env.idbFailure=true;await f.own(w,[2]);if(protection==='pending'){const retired=(await f.state(w)).items.find(x=>x.objectId===1);assert.equal(retired?.protected,true,'retired pending remains discoverable');assert.equal(retired.source,'substitution','retired object is no longer own');}if(protection==='unknown')assert(!(await f.state(w)).items.some(x=>x.objectId===1),'unknown protection remains hidden');f.env.padding=55*MiB;const next=await w.message('CACHE_CHECKLIST',{url:'https://field.test/pilot/construction-control/objects/2/checklist',scope:'new-own',attempt:'new-own'});if(protection==='clean'){assert.equal(next?.ok,true,'INTENDED_RED clean retired own bytes must be reclaimed for new assignment');for(const[name,c]of f.env.stores)if(name.includes('field-doc-'))assert(!(await c.match(path)),'retired aliases physically reclaimed');assert((await f.state(w)).cacheBytes<=100*MiB);}else{assert.equal(next?.ok,false,'protected old bytes cannot be evicted to fit new assignment');assert(await cache.match(path),'retired pending/unknown source retained');if(protection==='pending'){assert.equal(f.env.operations[0].wire,'RETIRED WIRE');assert.equal(await f.env.blobs[0].blob.text(),'RETIRED PHOTO');const retired=(await f.state(w)).items.find(x=>x.objectId===1);assert.equal(retired?.protected,true);assert.equal(retired.source,'substitution');f.env.network=false;for(const alias of ['control','object']){const response=await w.nav(1,'navigate',alias);assert.equal(response.status,200,'retired pending return path '+alias);assert.equal(Buffer.from(await crypto.subtle.digest('SHA-256',await response.arrayBuffer())).toString('hex'),originalHash,'exact retained document through '+alias);}}else{f.env.network=false;for(const alias of ['control','object'])assert.notEqual((await w.nav(1,'navigate',alias)).status,200,'UNKNOWN direct path remains closed');}}assert.equal(f.env.idbWrites,0);}});

if(results.some(x=>!x.pass)){console.error('INTENDED_RED FIELD-CACHE-RETENTION-001 public worker acceptance');process.exitCode=1;}else console.log('PASS: FIELD-CACHE-RETENTION-001 public worker acceptance');
